examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var tab = {{current}}

private struct NavLink: Identifiable {
    let key: String
    let label: String
    let badge: Int?
    var id: String { key }
}

private static let links = [
    NavLink(key: {{items.0.key}}, label: {{items.0.label}}, badge: nil),
    NavLink(key: {{items.1.key}}, label: {{items.1.label}}, badge: {{items.1.badge}}),
    NavLink(key: {{items.2.key}}, label: {{items.2.label}}, badge: nil),
    NavLink(key: {{items.3.key}}, label: {{items.3.label}}, badge: nil),
    NavLink(key: {{items.4.key}}, label: {{items.4.label}}, badge: nil),
    NavLink(key: {{items.5.key}}, label: {{items.5.label}}, badge: nil),
]

/// The links that fit stay in the row; the rest are in the More menu, so no link is clipped.
@ViewBuilder private func links(showing count: Int) -> some View {
    HStack(spacing: theme.spacing.space1) {
        ForEach(Self.links.prefix(count)) { link in
            Button {
                tab = link.key
            } label: {
                HStack(spacing: theme.spacing.space1_5) {
                    Text(link.label)
                    if let badge = link.badge {
                        Text(verbatim: String(badge))
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.dangerOnSolid)
                            .padding(.horizontal, 7)
                            .background(theme.colors.dangerSolid, in: Capsule())
                    }
                }
                .monarchTextStyle(.label)
                .foregroundStyle(tab == link.key ? theme.colors.accentStrong : theme.colors.textMuted)
                .padding(.horizontal, theme.spacing.space3)
                .frame(minHeight: 44)
                .background(tab == link.key ? theme.colors.accentSubtle : Color.clear, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
            }
            .buttonStyle(.plain)
            .accessibilityAddTraits(tab == link.key ? .isSelected : [])
        }
        Menu {
            ForEach(Self.links.dropFirst(count)) { link in
                Button(link.label) { tab = link.key }
            }
        } label: {
            HStack(spacing: theme.spacing.space1) {
                Text("More")
                Image(systemName: "chevron.down")
            }
            .monarchTextStyle(.label)
            .foregroundStyle(theme.colors.textMuted)
            .padding(.horizontal, theme.spacing.space3)
            .frame(minHeight: 44)
        }
    }
}

